import time, itertools, sys
n=5;m=3;M=40
N=m*n
verts=[(g,i) for g in range(m) for i in range(n)]
edges=[]
for g in range(m):
 for i in range(n):
  for j in range(i+1,n): edges.append((g*n+i,g*n+j))
for g in range(m-1):
 for i in range(n): edges.append((g*n+i,(g+1)*n+i))
E=len(edges)
class VarMap:
 def __init__(self): self.next=1
 def vlab(self,v,l): return 1 + v*(M+1)+l
 def diff(self,e,d): return 1+N*(M+1)+ e*M+(d-1)
 def top(self): return N*(M+1)+E*M
vm=VarMap(); top=vm.top()
clauses=[]
def add_exactly_one(lits):
 global top
 # pairwise for small
 clauses.append(lits[:])
 for i in range(len(lits)):
  li=lits[i]
  for lj in lits[i+1:]: clauses.append([-li,-lj])
# vertices exactly one
for v in range(N): add_exactly_one([vm.vlab(v,l) for l in range(M+1)])
# labels at most one
for l in range(M+1):
 lits=[vm.vlab(v,l) for v in range(N)]
 for i in range(len(lits)):
  for lj in lits[i+1:]: clauses.append([-lits[i],-lj])
# diff exactly one per edge
for e in range(E): add_exactly_one([vm.diff(e,d) for d in range(1,M+1)])
# each diff exactly one edge
for d in range(1,M+1): add_exactly_one([vm.diff(e,d) for e in range(E)])
# pair imply diff
for e,(u,v) in enumerate(edges):
 for a in range(M+1):
  vu=vm.vlab(u,a)
  for b in range(M+1):
   if a==b: continue
   clauses.append([-vu, -vm.vlab(v,b), vm.diff(e,abs(a-b))])
